create table if not exists firefly_calendar (calendar_id varchar(128) not null, calendar_version bigint not null, zone_id varchar(128) not null, working_days varchar(128) not null, holidays clob not null, extra_working_days clob not null, primary key (calendar_id, calendar_version));
create table if not exists firefly_trigger_inbox (event_id varchar(256) not null, event_type varchar(128) not null, idempotency_key varchar(256) primary key, payload clob not null, status varchar(32) not null, received_at timestamp not null, processed_at timestamp);
create table if not exists firefly_batch_execution (root_execution_id varchar(256) primary key, job_id varchar(128) not null, total_shards integer not null, completed_shards integer not null, failed_shards integer not null, retried_shards integer not null, input_records bigint not null, output_records bigint not null, progress_percent integer not null, sla_status varchar(32) not null, started_at timestamp not null, deadline timestamp not null, updated_at timestamp not null, fencing_token bigint not null default 0);
create table if not exists firefly_batch_shard (root_execution_id varchar(256) not null, shard_index integer not null, attempt integer not null, status varchar(32) not null, input_records bigint not null, output_records bigint not null, checkpoint_id varchar(256) not null, checksum varchar(256) not null, error_message varchar(4096) not null, completed_at timestamp not null, primary key (root_execution_id, shard_index, attempt));
create table if not exists firefly_batch_checkpoint (checkpoint_id varchar(256) primary key, root_execution_id varchar(256) not null, shard_index integer not null, attempt integer not null, location varchar(1024) not null, checksum varchar(256) not null, created_at timestamp not null);
